def send_email(from_email, to, subject, from_name=None, cc=None, bcc=None, reply_to=None, text_body=None, html_body=None, headers=None, tags=None, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0175000" if __import__("os").path.isdir("./environment_mix/0175000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    email_re = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(x):
        if x is None:
            return None
        if isinstance(x, datetime.datetime):
            return x.astimezone(datetime.timezone.utc)
        if isinstance(x, str):
            s = x.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
            except ValueError:
                return None
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        return None

    def _day_boundary_utc(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _validate_recipient_list(lst, name):
        if lst is None:
            return []
        if not isinstance(lst, list):
            return _err("VALIDATION_ERROR", f"'{name}' must be an array")
        out = []
        for i, it in enumerate(lst):
            if not isinstance(it, dict):
                return _err("VALIDATION_ERROR", f"'{name}[{i}]' must be an object")
            extra = set(it.keys()) - {"email", "name"}
            if extra:
                return _err("VALIDATION_ERROR", f"'{name}[{i}]' contains unknown fields: {sorted(list(extra))}")
            if "email" not in it:
                return _err("VALIDATION_ERROR", f"'{name}[{i}].email' is required")
            em = it.get("email")
            if not isinstance(em, str) or not email_re.match(em.strip()):
                return _err("VALIDATION_ERROR", f"'{name}[{i}].email' must be a valid email address")
            nm = it.get("name")
            if nm is not None and not isinstance(nm, str):
                return _err("VALIDATION_ERROR", f"'{name}[{i}].name' must be a string when provided")
            out.append({"email": em.strip(), "name": nm})
        return out

    def _record_request(send_requests, api_key_id, status, resolved_payload=None, result_message_id=None, error_message=None):
        now_iso = _iso(now)
        row = {
            "id": _new_id("req"),
            "api_key_id": api_key_id,
            "tool_name": "send-email",
            "request_parameters": {},  # tool schema: empty object only
            "resolved_payload": resolved_payload,
            "result_message_id": result_message_id,
            "status": status,
            "error_message": error_message,
            "ip_address": None,
            "user_agent": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        send_requests.append(row)
        return row

    def _count_recent_requests(send_requests, api_key_id, window_seconds=60):
        cutoff = now - datetime.timedelta(seconds=window_seconds)
        c = 0
        for r in send_requests:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            created = _parse_dt(r.get("created_at"))
            if created is None:
                continue
            if created >= cutoff:
                c += 1
        return c

    # ---- Validate input payload types and constraints ----
    if not isinstance(from_email, str) or not email_re.match(from_email.strip()):
        return _err("VALIDATION_ERROR", "'from_email' must be a valid email address")
    if from_name is not None and not isinstance(from_name, str):
        return _err("VALIDATION_ERROR", "'from_name' must be a string when provided")
    if not isinstance(subject, str):
        return _err("VALIDATION_ERROR", "'subject' must be a string")
    if len(subject) > 998:
        return _err("VALIDATION_ERROR", "length(subject) must be <= 998")
    if text_body is not None and not isinstance(text_body, str):
        return _err("VALIDATION_ERROR", "'text_body' must be a string when provided")
    if html_body is not None and not isinstance(html_body, str):
        return _err("VALIDATION_ERROR", "'html_body' must be a string when provided")
    if text_body is None and html_body is None:
        return _err("VALIDATION_ERROR", "At least one of 'text_body' or 'html_body' must be provided")

    to_v = _validate_recipient_list(to, "to")
    if isinstance(to_v, dict):
        return to_v
    cc_v = _validate_recipient_list(cc, "cc")
    if isinstance(cc_v, dict):
        return cc_v
    bcc_v = _validate_recipient_list(bcc, "bcc")
    if isinstance(bcc_v, dict):
        return bcc_v
    reply_to_v = _validate_recipient_list(reply_to, "reply_to")
    if isinstance(reply_to_v, dict):
        return reply_to_v

    if len(to_v) + len(cc_v) + len(bcc_v) < 1:
        return _err("VALIDATION_ERROR", "At least one recipient across ('to','cc','bcc') is required")

    if headers is not None:
        if not isinstance(headers, dict):
            return _err("VALIDATION_ERROR", "'headers' must be an object when provided")
        for k, v in headers.items():
            if not isinstance(k, str):
                return _err("VALIDATION_ERROR", "'headers' keys must be strings")
            if not isinstance(v, str):
                return _err("VALIDATION_ERROR", f"'headers.{k}' must be a string")
    if tags is not None:
        if not isinstance(tags, list):
            return _err("VALIDATION_ERROR", "'tags' must be an array when provided")
        for i, t in enumerate(tags):
            if not isinstance(t, str):
                return _err("VALIDATION_ERROR", f"'tags[{i}]' must be a string")

    # ---- Resolve authentication context (ambient): find an active key capable of sending ----
    api_keys = _load("api_keys.json")
    send_requests = _load("send_requests.json")
    email_messages = _load("email_messages.json")
    email_recipients = _load("email_recipients.json")
    provider_attempts = _load("email_provider_attempts.json")

    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    if not active_keys:
        # No key can serve the request: no place to log a send_requests row with valid FK.
        return _err("UNAUTHORIZED", "No active API key available to authenticate this request")

    # choose a working combination: key must have valid quotas and rate limits configured
    chosen = None
    for k in active_keys:
        rlm = k.get("rate_limit_per_minute")
        dsl = k.get("daily_send_limit")
        if isinstance(rlm, int) and 1 <= rlm <= 6000 and isinstance(dsl, int) and dsl >= 0:
            chosen = k
            break
    if chosen is None:
        return _err("UNAUTHORIZED", "No active API key with valid limits available to authenticate this request")

    api_key_id = chosen.get("id")

    # ---- Daily counter normalization/reset check ----
    ds_date = _parse_dt(chosen.get("daily_send_count_date"))
    today0 = _day_boundary_utc(now)
    if ds_date is None or ds_date != today0:
        # reset counter (simulating daily job boundary normalization)
        chosen["daily_send_count_date"] = _iso(today0)
        chosen["daily_send_count"] = 0

    # ---- Enforce rate limit per minute (sliding window by send_requests entries) ----
    rate_limit = int(chosen.get("rate_limit_per_minute"))
    recent = _count_recent_requests(send_requests, api_key_id, 60)
    if recent >= rate_limit:
        _record_request(
            send_requests,
            api_key_id=api_key_id,
            status="rejected",
            resolved_payload=None,
            result_message_id=None,
            error_message=f"rate limit exceeded ({rate_limit}/min)"
        )
        _save("send_requests.json", send_requests)
        chosen["last_used_at"] = _iso(now)
        chosen["updated_at"] = _iso(now)
        _save("api_keys.json", api_keys)
        return _err("RATE_LIMIT", f"Rate limit exceeded ({rate_limit}/min)")

    # ---- Enforce daily send limit (0 = unlimited) and increment atomically in store ----
    daily_limit = int(chosen.get("daily_send_limit"))
    daily_count = int(chosen.get("daily_send_count") if isinstance(chosen.get("daily_send_count"), int) else 0)
    if daily_limit != 0 and daily_count + 1 > daily_limit:
        _record_request(
            send_requests,
            api_key_id=api_key_id,
            status="rejected",
            resolved_payload=None,
            result_message_id=None,
            error_message=f"daily send limit reached ({daily_limit}/day)"
        )
        _save("send_requests.json", send_requests)
        chosen["last_used_at"] = _iso(now)
        chosen["updated_at"] = _iso(now)
        _save("api_keys.json", api_keys)
        return _err("QUOTA_EXCEEDED", f"Daily send limit reached ({daily_limit}/day)")

    # ---- Create message + recipients + initial provider attempt ----
    msg_id = _new_id("eml")
    now_iso = _iso(now)
    resolved_payload = {
        "from_email": from_email.strip(),
        "from_name": from_name,
        "to": to_v,
        "cc": cc_v,
        "bcc": bcc_v,
        "reply_to": reply_to_v,
        "subject": subject,
        "text_body": text_body,
        "html_body": html_body,
        "headers": headers,
        "tags": tags,
    }

    msg_row = {
        "id": msg_id,
        "api_key_id": api_key_id,
        "status": "queued",
        "from_email": from_email.strip(),
        "from_name": from_name,
        "subject": subject,
        "text_body": text_body,
        "html_body": html_body,
        "headers": headers,
        "reply_to": reply_to_v if reply_to is not None else None,
        "tags": tags,
        "provider_message_id": None,
        "error_code": None,
        "error_message": None,
        "queued_at": now_iso,
        "sent_at": None,
        "finalized_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    # Recipient uniqueness per (message_id, kind, email)
    seen = set()
    rcp_rows = []
    for kind, lst in (("to", to_v), ("cc", cc_v), ("bcc", bcc_v)):
        for r in lst:
            key = (kind, r["email"].lower())
            if key in seen:
                continue
            seen.add(key)
            rcp_rows.append({
                "id": _new_id("rcp"),
                "message_id": msg_id,
                "kind": kind,
                "email": r["email"],
                "name": r.get("name"),
                "status": "pending",
                "provider_recipient_id": None,
                "error_code": None,
                "error_message": None,
                "created_at": now_iso,
                "updated_at": now_iso,
            })

    if len(rcp_rows) < 1:
        _record_request(
            send_requests,
            api_key_id=api_key_id,
            status="rejected",
            resolved_payload=None,
            result_message_id=None,
            error_message="no recipients after deduplication"
        )
        _save("send_requests.json", send_requests)
        chosen["last_used_at"] = _iso(now)
        chosen["updated_at"] = _iso(now)
        _save("api_keys.json", api_keys)
        return _err("VALIDATION_ERROR", "At least one unique recipient is required")

    # Create initial provider attempt as queued (dispatcher "queued initial attempts")
    att_row = {
        "id": _new_id("att"),
        "message_id": msg_id,
        "attempt_no": 1,
        "provider": "resend",
        "status": "queued",
        "request_payload": resolved_payload,
        "response_payload": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    # Persist: increment counters, write all rows, then record accepted request
    chosen["daily_send_count"] = daily_count + 1
    chosen["last_used_at"] = _iso(now)
    chosen["updated_at"] = _iso(now)

    email_messages.append(msg_row)
    email_recipients.extend(rcp_rows)
    provider_attempts.append(att_row)

    req_row = _record_request(
        send_requests,
        api_key_id=api_key_id,
        status="accepted",
        resolved_payload=resolved_payload,
        result_message_id=msg_id,
        error_message=None
    )

    _save("api_keys.json", api_keys)
    _save("email_messages.json", email_messages)
    _save("email_recipients.json", email_recipients)
    _save("email_provider_attempts.json", provider_attempts)
    _save("send_requests.json", send_requests)

    return {
        "message": {
            "id": msg_row["id"],
            "status": msg_row["status"],
            "queued_at": msg_row["queued_at"],
        },
        "request": {
            "id": req_row["id"],
            "status": req_row["status"],
        },
        "meta": {
            "latency_ms": int((time.time() - t0) * 1000)
        }
    }

def get_auth_context(api_key=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0175000" if __import__("os").path.isdir("./environment_mix/0175000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(x):
        if x is None:
            return None
        if isinstance(x, datetime.datetime):
            return x.astimezone(datetime.timezone.utc)
        if isinstance(x, str):
            s = x.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
            except ValueError:
                return None
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        return None

    def _day_boundary_utc(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)

    api_keys = _load("api_keys.json")
    send_requests = _load("send_requests.json")

    # Validate
    if api_key is not None and not isinstance(api_key, str):
        return _err("VALIDATION_ERROR", "'api_key' must be a string")

    # Authenticate by id or prefix (never by hash)
    key_row = None
    token = api_key.strip() if isinstance(api_key, str) else None
    if token:
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("id") == token or k.get("key_prefix") == token:
                key_row = k
                break

    if key_row is None:
        # Unauthenticated; still provide a structured response (tool description says UNAUTHORIZED when missing/invalid)
        return _err("UNAUTHORIZED", "API key missing or invalid")

    if key_row.get("status") == "revoked":
        return _err("UNAUTHORIZED", "API key revoked")

    # Normalize/reset daily counter boundary (observed behaviour)
    ds_date = _parse_dt(key_row.get("daily_send_count_date"))
    today0 = _day_boundary_utc(now)
    if ds_date is None or ds_date != today0:
        key_row["daily_send_count_date"] = _iso(today0)
        key_row["daily_send_count"] = 0
        key_row["updated_at"] = _iso(now)
        _save("api_keys.json", api_keys)

    # Rate usage: count requests in last 60s for this key
    cutoff = now - datetime.timedelta(seconds=60)
    used_1m = 0
    for r in send_requests:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != key_row.get("id"):
            continue
        created = _parse_dt(r.get("created_at"))
        if created is None:
            continue
        if created >= cutoff:
            used_1m += 1

    daily_limit = key_row.get("daily_send_limit")
    daily_count = key_row.get("daily_send_count")

    return {
        "api_key": {
            "id": key_row.get("id"),
            "key_prefix": key_row.get("key_prefix"),
            "label": key_row.get("label"),
            "status": key_row.get("status"),
            "created_at": key_row.get("created_at"),
            "last_used_at": key_row.get("last_used_at"),
        },
        "limits": {
            "rate_limit_per_minute": key_row.get("rate_limit_per_minute"),
            "rate_limit_used_last_minute": used_1m,
            "daily_send_limit": daily_limit,
            "daily_send_count": daily_count,
            "daily_send_count_date": key_row.get("daily_send_count_date"),
        },
        "meta": {
            "latency_ms": int((time.time() - t0) * 1000)
        }
    }

def list_email_messages(api_key, status=None, tag=None, from_email=None, provider_message_id=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0175000" if __import__("os").path.isdir("./environment_mix/0175000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return str(dt)

    def _parse_iso(s, field_name):
        if s is None:
            return None
        if not isinstance(s, str):
            return ("__bad__", _err("VALIDATION_ERROR", f"{field_name} must be an ISO-8601 timestamp string"))
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return ("__bad__", _err("VALIDATION_ERROR", f"{field_name} must be a valid ISO-8601 timestamp"))

    def _mk_request_row(api_key_id, status_val, error_message=None):
        rid = "sr_" + os.urandom(12).hex()
        ts = _iso(now)
        return {
            "id": rid,
            "api_key_id": api_key_id,
            "tool_name": "send-email",
            "request_parameters": {},   # tool schema: empty object
            "resolved_payload": None,
            "result_message_id": None,
            "status": status_val,       # accepted|rejected|errored
            "error_message": error_message,
            "ip_address": None,
            "user_agent": None,
            "created_at": ts,
            "updated_at": ts
        }

    def _find_api_key_row(api_key_value, api_keys_rows):
        # Authenticate by client-visible value: accept api_keys.id OR api_keys.key_prefix.
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None
        v = api_key_value.strip()
        for r in api_keys_rows:
            if r.get("id") == v:
                return r
        for r in api_keys_rows:
            if r.get("key_prefix") == v:
                return r
        return None

    def _enforce_rate_limit(key_row, send_req_rows):
        # Sliding window: count requests for this key in last 60s.
        rl = key_row.get("rate_limit_per_minute")
        try:
            rl = int(rl)
        except Exception:
            rl = None
        if rl is None or rl < 1:
            return (False, "API key has invalid rate_limit_per_minute")
        window_start = now - datetime.timedelta(seconds=60)
        c = 0
        for r in send_req_rows:
            if r.get("api_key_id") != key_row.get("id"):
                continue
            ca = r.get("created_at")
            if not isinstance(ca, str):
                continue
            parsed = _parse_iso(ca, "created_at")
            if isinstance(parsed, tuple) and parsed[0] == "__bad__":
                continue
            if parsed >= window_start:
                c += 1
        if c >= rl:
            return (False, f"Rate limit exceeded: {rl}/minute")
        return (True, None)

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string")

    allowed_status = {"queued", "sending", "delivered", "bounced", "failed", "cancelled"}
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in allowed_status:
            return _err("VALIDATION_ERROR", "status must be one of queued,sending,delivered,bounced,failed,cancelled")

    if tag is not None and not isinstance(tag, str):
        return _err("VALIDATION_ERROR", "tag must be a string")
    if from_email is not None and not isinstance(from_email, str):
        return _err("VALIDATION_ERROR", "from_email must be a string")
    if provider_message_id is not None and not isinstance(provider_message_id, str):
        return _err("VALIDATION_ERROR", "provider_message_id must be a string")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")

    ca = _parse_iso(created_after, "created_after")
    if isinstance(ca, tuple) and ca[0] == "__bad__":
        return ca[1]
    cb = _parse_iso(created_before, "created_before")
    if isinstance(cb, tuple) and cb[0] == "__bad__":
        return cb[1]

    # Decode cursor (opaque)
    cursor_created_at = None
    cursor_id = None
    if cursor is not None:
        if not isinstance(cursor, str):
            return _err("VALIDATION_ERROR", "cursor must be a string")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            payload = json.loads(raw.decode("utf-8"))
            cursor_created_at = payload.get("created_at")
            cursor_id = payload.get("id")
            if not isinstance(cursor_created_at, str) or not isinstance(cursor_id, str):
                return _err("VALIDATION_ERROR", "cursor is invalid")
        except (ValueError, json.JSONDecodeError):
            return _err("VALIDATION_ERROR", "cursor is invalid")

    # Load data
    api_keys = _load("api_keys.json")
    send_requests = _load("send_requests.json")
    email_messages = _load("email_messages.json")

    # Authenticate
    key_row = _find_api_key_row(api_key, api_keys)
    if key_row is None:
        # Must record request dynamics; use placeholder api_key_id if unknown.
        sr = _mk_request_row("unknown", "rejected", "UNAUTHORIZED: invalid API key")
        send_requests.append(sr)
        _save("send_requests.json", send_requests)
        return _err("UNAUTHORIZED", "API key missing or invalid")

    # If revoked => FORBIDDEN per tool description (map to UNAUTHORIZED code set: use UNAUTHORIZED with detail)
    if key_row.get("status") != "active":
        sr = _mk_request_row(key_row.get("id"), "rejected", "FORBIDDEN: API key revoked")
        send_requests.append(sr)
        _save("send_requests.json", send_requests)
        return _err("UNAUTHORIZED", "API key is revoked", forbidden=True)

    # Rate limit (even for reads, per observable dynamics requirement)
    ok_rl, rl_msg = _enforce_rate_limit(key_row, send_requests)
    if not ok_rl:
        sr = _mk_request_row(key_row.get("id"), "rejected", rl_msg)
        send_requests.append(sr)
        _save("send_requests.json", send_requests)
        return _err("RATE_LIMIT", rl_msg)

    # Update key last_used_at
    key_row["last_used_at"] = _iso(now)
    key_row["updated_at"] = _iso(now)
    _save("api_keys.json", api_keys)

    # Log request as accepted (it's a successful authenticated call)
    sr = _mk_request_row(key_row.get("id"), "accepted", None)
    send_requests.append(sr)
    _save("send_requests.json", send_requests)

    # Filter messages visible to key
    rows = [m for m in email_messages if m.get("api_key_id") == key_row.get("id")]

    if status is not None:
        rows = [m for m in rows if m.get("status") == status]
    if from_email is not None:
        rows = [m for m in rows if m.get("from_email") == from_email]
    if provider_message_id is not None:
        rows = [m for m in rows if m.get("provider_message_id") == provider_message_id]
    if tag is not None:
        def _has_tag(m):
            tg = m.get("tags")
            return isinstance(tg, list) and tag in tg
        rows = [m for m in rows if _has_tag(m)]
    if ca is not None:
        def _after(m):
            p = _parse_iso(m.get("created_at"), "created_at")
            if isinstance(p, tuple) and p[0] == "__bad__":
                return False
            return p >= ca
        rows = [m for m in rows if _after(m)]
    if cb is not None:
        def _before(m):
            p = _parse_iso(m.get("created_at"), "created_at")
            if isinstance(p, tuple) and p[0] == "__bad__":
                return False
            return p < cb
        rows = [m for m in rows if _before(m)]

    def _sort_key(m):
        p = _parse_iso(m.get("created_at"), "created_at")
        if isinstance(p, tuple) and p[0] == "__bad__":
            p = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (p, m.get("id") or "")
    rows.sort(key=_sort_key, reverse=True)

    # Apply cursor pagination (created_at desc, id desc)
    if cursor_created_at is not None and cursor_id is not None:
        cursor_dt = _parse_iso(cursor_created_at, "cursor.created_at")
        if isinstance(cursor_dt, tuple) and cursor_dt[0] == "__bad__":
            return cursor_dt[1]
        filtered = []
        for m in rows:
            md = _parse_iso(m.get("created_at"), "created_at")
            if isinstance(md, tuple) and md[0] == "__bad__":
                continue
            mid = m.get("id") or ""
            if md < cursor_dt:
                filtered.append(m)
            elif md == cursor_dt and mid < cursor_id:
                filtered.append(m)
        rows = filtered

    total = len(rows)
    page = rows[:limit]
    has_more = total > limit

    next_cursor = None
    if has_more and page:
        last = page[-1]
        payload = {"created_at": last.get("created_at"), "id": last.get("id")}
        b = json.dumps(payload, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(b).decode("utf-8").rstrip("=")

    latency_ms = int((time.time() - t0) * 1000)
    # Record latency/status in send_requests row we wrote (best-effort update)
    sr["updated_at"] = _iso(now)
    sr["resolved_payload"] = {"endpoint": "list-email-messages", "latency_ms": latency_ms}

    _save("send_requests.json", send_requests)

    return {
        "object": "list",
        "data": page,
        "total": total,
        "limit": limit,
        "has_more": has_more,
