    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _dt_parse(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.fromtimestamp(float(v), tz=datetime.timezone.utc)
            except Exception:
                return None
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _dt_to_iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _day_boundary_utc(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        dt = dt.astimezone(datetime.timezone.utc)
        return datetime.datetime(dt.year, dt.month, dt.day, 0, 0, 0, tzinfo=datetime.timezone.utc)

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string")

    if message_id is not None and (not isinstance(message_id, str) or not message_id.strip()):
        return _err("VALIDATION_ERROR", "message_id must be a non-empty string when provided")

    allowed_kind = {"to", "cc", "bcc", "reply_to"}
    if kind is not None:
        if not isinstance(kind, str) or kind not in allowed_kind:
            return _err("VALIDATION_ERROR", "kind must be one of: to, cc, bcc, reply_to")

    allowed_status = {"pending", "delivered", "bounced", "failed"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _err("VALIDATION_ERROR", "status must be one of: pending, delivered, bounced, failed")

    if email is not None and (not isinstance(email, str) or not email.strip()):
        return _err("VALIDATION_ERROR", "email must be a non-empty string when provided")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500")

    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")

    # Load store
    api_keys = _load("api_keys.json")
    messages = _load("email_messages.json")
    recipients = _load("email_recipients.json")
    attempts = _load("email_provider_attempts.json")
    send_requests = _load("send_requests.json")

    # Auth: match by id or by key_prefix (client-visible); do NOT compare against key_hash.
    ak = None
    for row in api_keys:
        if not isinstance(row, dict):
            continue
        if row.get("id") == api_key or row.get("key_prefix") == api_key:
            ak = row
            break

    # Helper to log a request (best-effort, but must not raise)
    def _log(status_s, error_message=None):
        try:
            req_id = _new_id("req")
            created = now
            send_requests.append({
                "id": req_id,
                "api_key_id": ak.get("id") if isinstance(ak, dict) else "unknown",
                "tool_name": "send-email",
                "request_parameters": {},
                "resolved_payload": None,
                "result_message_id": None,
                "status": status_s,
                "error_message": error_message,
                "ip_address": None,
                "user_agent": None,
                "created_at": _dt_to_iso(created),
                "updated_at": _dt_to_iso(created),
            })
            _save("send_requests.json", send_requests)
        except Exception:
            pass

    # If missing/invalid key => UNAUTHORIZED
    if ak is None:
        _log("rejected", "UNAUTHORIZED: invalid api_key")
        return _err("UNAUTHORIZED", "Invalid API key")

    # Revoked => FORBIDDEN (tool description)
    if ak.get("status") == "revoked":
        _log("rejected", "FORBIDDEN: api_key revoked")
        return _err("UNAUTHORIZED", "API key is revoked", detail="FORBIDDEN")

    # Enforce rate limit for reads too (observable dynamics)
    # Sliding window: count send_requests by api_key_id in last 60s
    try:
        rl = ak.get("rate_limit_per_minute")
        if not isinstance(rl, int) or rl < 1 or rl > 6000:
            # stored data invalid; treat as service error for this key
            _log("errored", "Invalid rate_limit_per_minute configuration")
            return _err("CONFLICT", "API key configuration invalid (rate_limit_per_minute)")
        window_start = now - datetime.timedelta(seconds=60)
        c = 0
        akid = ak.get("id")
        for r in send_requests:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != akid:
                continue
            dt = _dt_parse(r.get("created_at"))
            if dt is None:
                continue
            if dt >= window_start:
                c += 1
        if c >= rl:
            _log("rejected", "RATE_LIMIT exceeded")
            return _err("RATE_LIMIT", "Rate limit exceeded")
    except Exception:
        _log("errored", "Rate limit evaluation failed")
        return _err("CONFLICT", "Unable to evaluate rate limit")

    # Visibility: recipients visible if their message api_key_id equals this key's id
    akid = ak.get("id")

    # If message_id provided, ensure message exists and is visible
    msg = None
    if message_id is not None:
        for m in messages:
            if isinstance(m, dict) and m.get("id") == message_id and m.get("api_key_id") == akid:
                msg = m
                break
        if msg is None:
            _log("rejected", "NOT_FOUND: message not found or not visible")
            return _err("NOT_FOUND", "Message not found")

    # Cursor decode: base64url of JSON {"o": <offset>}
    offset = 0
    if cursor:
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            off = obj.get("o")
            if not isinstance(off, int) or off < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor")
            offset = off
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor")

    # Build index of visible message_ids
    visible_message_ids = set()
    if message_id is not None:
        visible_message_ids.add(message_id)
    else:
        for m in messages:
            if isinstance(m, dict) and m.get("api_key_id") == akid and isinstance(m.get("id"), str):
                visible_message_ids.add(m["id"])

    # Filter recipients
    rows = []
    for r in recipients:
        if not isinstance(r, dict):
            continue
        mid = r.get("message_id")
        if mid not in visible_message_ids:
            continue
        if kind is not None:
            # tool supports "reply_to" but schema does not; return empty when requested
            if kind == "reply_to":
                continue
            if r.get("kind") != kind:
                continue
        if status is not None and r.get("status") != status:
            continue
        if email is not None and r.get("email") != email:
            continue
        rows.append(r)

    # Sort deterministically: created_at desc, id desc
    def _sort_key(r):
        dt = _dt_parse(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (dt, r.get("id") or "")
    rows.sort(key=_sort_key, reverse=True)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"o": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    # Update key last_used_at (best-effort) and log call
    try:
        ak["last_used_at"] = _dt_to_iso(now)
        ak["updated_at"] = _dt_to_iso(now)
        _save("api_keys.json", api_keys)
    except Exception:
        pass

    _log("accepted", None)

    return {
        "object": "list",
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
        }
    }

