                "result_message_id": None,
                "status": status_s,
                "error_message": error_message,
                "ip_address": None,
                "user_agent": None,
                "created_at": _dt_to_iso(now),
                "updated_at": _dt_to_iso(now),
            })
            _save("send_requests.json", send_requests)
        except Exception:
            pass

    if ak is None:
        _log("rejected", "UNAUTHORIZED: invalid api_key")
        return _err("UNAUTHORIZED", "Invalid API key")

    if ak.get("status") == "revoked":
        _log("rejected", "FORBIDDEN: api_key revoked")
        return _err("UNAUTHORIZED", "API key is revoked", detail="FORBIDDEN")

    # Rate limit (reads included)
    try:
        rl = ak.get("rate_limit_per_minute")
        if not isinstance(rl, int) or rl < 1 or rl > 6000:
            _log("errored", "Invalid rate_limit_per_minute configuration")
            return _err("CONFLICT", "API key configuration invalid (rate_limit_per_minute)")
        window_start = now - datetime.timedelta(seconds=60)
        c = 0
        akid = ak.get("id")
        for r in send_requests:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != akid:
                continue
            dt = _dt_parse(r.get("created_at"))
            if dt is None:
                continue
            if dt >= window_start:
                c += 1
        if c >= rl:
            _log("rejected", "RATE_LIMIT exceeded")
            return _err("RATE_LIMIT", "Rate limit exceeded")
    except Exception:
        _log("errored", "Rate limit evaluation failed")
        return _err("CONFLICT", "Unable to evaluate rate limit")

    akid = ak.get("id")

    msg = None
    if message_id is not None:
        for m in messages:
            if isinstance(m, dict) and m.get("id") == message_id and m.get("api_key_id") == akid:
                msg = m
                break
        if msg is None:
            _log("rejected", "NOT_FOUND: message not found or not visible")
            return _err("NOT_FOUND", "Message not found")

    offset = 0
    if cursor:
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            off = obj.get("o")
            if not isinstance(off, int) or off < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor")
            offset = off
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor")

    visible_message_ids = set()
    if message_id is not None:
        visible_message_ids.add(message_id)
    else:
        for m in messages:
            if isinstance(m, dict) and m.get("api_key_id") == akid and isinstance(m.get("id"), str):
                visible_message_ids.add(m["id"])

    rows = []
    for a in attempts:
        if not isinstance(a, dict):
            continue
        mid = a.get("message_id")
        if mid not in visible_message_ids:
            continue
        if status is not None and a.get("status") != status:
            continue
        if provider is not None and a.get("provider") != provider:
            continue
        rows.append(a)

    # Order by started_at desc then created_at desc then id desc
    def _sort_key(a):
        sdt = _dt_parse(a.get("started_at")) or _dt_parse(a.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        cdt = _dt_parse(a.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (sdt, cdt, a.get("id") or "")
    rows.sort(key=_sort_key, reverse=True)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"o": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    try:
        ak["last_used_at"] = _dt_to_iso(now)
        ak["updated_at"] = _dt_to_iso(now)
        _save("api_keys.json", api_keys)
    except Exception:
        pass

    _log("accepted", None)

    return {
        "object": "list",
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
        }
    }

def cancel_email_message(api_key, message_id, reason=None, **_extra):
    import json, os, datetime, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0175000" if __import__("os").path.isdir("./environment_mix/0175000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return now.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:26]}"

    def _log_send_request(send_requests_rows, api_key_id, status, error_message=None, result_message_id=None, resolved_payload=None):
        ts = _iso(now)
        row = {
            "id": _new_id("req"),
            "api_key_id": api_key_id,
            "tool_name": "send-email",
            "request_parameters": {},  # schema: empty object only
            "resolved_payload": resolved_payload,
            "result_message_id": result_message_id,
            "status": status,  # accepted|rejected|errored
            "error_message": error_message,
            "ip_address": None,
            "user_agent": None,
            "created_at": ts,
            "updated_at": ts,
        }
        send_requests_rows.append(row)
        return row

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    # -------- Validate inputs --------
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string")
    if not isinstance(message_id, str) or not message_id.strip():
        return _err("VALIDATION_ERROR", "message_id is required and must be a non-empty string")
    if reason is not None and not isinstance(reason, str):
        return _err("VALIDATION_ERROR", "reason must be a string when provided")

    # -------- Load datastore --------
    api_keys = _load("api_keys.json")
    email_messages = _load("email_messages.json")
    send_requests = _load("send_requests.json")

    if not isinstance(api_keys, list) or not isinstance(email_messages, list) or not isinstance(send_requests, list):
        # Datastore corruption/format unexpected
        return _err("ERRORED" if False else "VALIDATION_ERROR", "Datastore is not in expected format")

    # -------- Authenticate --------
    # Vendor rule: authenticate by matching client-visible value or its id.
    # We only have api_keys.id and key_prefix/hash; accept id match or prefix match.
    key_row = None
    api_key_in = api_key.strip()

    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == api_key_in:
            key_row = k
            break
    if key_row is None:
        # try prefix match (only if unique and non-empty)
        candidates = []
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if isinstance(k.get("key_prefix"), str) and k.get("key_prefix") and api_key_in.startswith(k.get("key_prefix")):
                candidates.append(k)
        if len(candidates) == 1:
            key_row = candidates[0]

    # We must record every call into send_requests before returning (schema's request log).
    # When auth cannot be resolved, we cannot satisfy fk(api_key_id). Use a real existing key as the log owner if possible.
    # Prefer an active key; otherwise any key. If no keys exist, return UNAUTHORIZED without logging (cannot persist valid row).
    def _pick_any_key_id():
        if isinstance(api_keys, list):
            for k in api_keys:
                if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str):
                    return k["id"]
            for k in api_keys:
                if isinstance(k, dict) and isinstance(k.get("id"), str):
                    return k["id"]
        return None

    if key_row is None:
        fallback_id = _pick_any_key_id()
        if fallback_id is not None:
            _log_send_request(send_requests, fallback_id, status="rejected", error_message="unauthorized: invalid api key")
            _save("send_requests.json", send_requests)
        return _err("UNAUTHORIZED", "API key is missing or invalid")

    api_key_id = key_row.get("id")
    if not isinstance(api_key_id, str) or not api_key_id:
        return _err("UNAUTHORIZED", "API key is missing or invalid")

    # If revoked: per rules in spec (for send-email tool) treat as rejected. Tool text mentions FORBIDDEN,
    # but allowed codes list does not include FORBIDDEN. Use UNAUTHORIZED vs CONFLICT? We will use UNAUTHORIZED is incorrect.
    # Use CONFLICT? No. Best fit: UNAUTHORIZED with clear message.
    if key_row.get("status") == "revoked":
        _log_send_request(send_requests, api_key_id, status="rejected", error_message="api key revoked")
        _save("send_requests.json", send_requests)
        return _err("UNAUTHORIZED", "API key is revoked")

    # -------- Find message --------
    msg = None
    for m in email_messages:
        if isinstance(m, dict) and m.get("id") == message_id:
            msg = m
            break
    if msg is None:
        _log_send_request(send_requests, api_key_id, status="rejected", error_message="message not found", result_message_id=None)
        _save("send_requests.json", send_requests)
        return _err("NOT_FOUND", "Email message does not exist")

    # Basic visibility: only allow cancelling messages created with this api key
    if msg.get("api_key_id") != api_key_id:
        _log_send_request(send_requests, api_key_id, status="rejected", error_message="message not found", result_message_id=None)
        _save("send_requests.json", send_requests)
        return _err("NOT_FOUND", "Email message does not exist")

    # -------- Enforce lifecycle / transition --------
    status = msg.get("status")
    terminal = {"delivered", "bounced", "failed", "cancelled"}

    # Only queued -> cancelled is allowed by tool contract.
    if status != "queued":
        # Important audit fix: do NOT return INVALID_TRANSITION for terminal; tool description says refuse cancellation
        # if already left queued or is terminal; that is a conflict with requested operation.
        # Use CONFLICT and explain rule.
        _log_send_request(
            send_requests,
            api_key_id,
            status="rejected",
            error_message=f"cannot cancel: message status is '{status}' (only 'queued' messages can be cancelled)",
            result_message_id=message_id,
        )
        _save("send_requests.json", send_requests)
        return _err(
            "CONFLICT",
            f"Cancellation refused: message is in status '{status}'. Business rule: only messages in 'queued' may transition to 'cancelled'.",
            current_status=status,
            allowed_from=["queued"],
            requested="cancelled",
        )

    # -------- Apply mutation --------
    ts = _iso(now)
    msg["status"] = "cancelled"
    msg["updated_at"] = ts
    msg["finalized_at"] = ts  # terminal => finalized_at must be not null
    # queued_at remains as originally set; sent_at remains null.
    # Record reason into error_message for audit/debugging (no dedicated field exists for cancel reason).
    if isinstance(reason, str) and reason.strip():
        msg["error_code"] = "cancelled_by_user"
        msg["error_message"] = reason.strip()
    else:
        msg["error_code"] = "cancelled_by_user"
        msg["error_message"] = msg.get("error_message") or "Message cancelled before first provider attempt."

    # Update key last_used_at/updated_at (service dynamics)
    key_row["last_used_at"] = ts
    key_row["updated_at"] = ts

    # Log request (accepted, since mutation succeeded)
    _log_send_request(
        send_requests,
        api_key_id,
        status="accepted",
        error_message=None,
        result_message_id=message_id,
        resolved_payload=None,
    )

    # Persist
    _save("email_messages.json", email_messages)
    _save("api_keys.json", api_keys)
    _save("send_requests.json", send_requests)

    latency_ms = int((time.time() - t0) * 1000)

    return {
        "message": {
            "id": msg.get("id"),
            "api_key_id": msg.get("api_key_id"),
            "status": msg.get("status"),
            "finalized_at": msg.get("finalized_at"),
            "updated_at": msg.get("updated_at"),
            "error_code": msg.get("error_code"),
            "error_message": msg.get("error_message"),
        },
        "meta": {
            "latency_ms": latency_ms
        }
    }
